const $=(s)=>document.querySelector(s);
let lang=new URLSearchParams(location.search).get('lang')||localStorage.getItem('statob-language')||'en';
if(!['en','ms'].includes(lang))lang='en';
const t=(en,ms)=>lang==='ms'?ms:en;
const pages={index:['Home','Utama'],about:['About','Tentang Kami'],tourism:['Tourism & Culture','Pelancongan & Budaya'],trade:['Trade & Commerce','Perdagangan'],investment:['Investment','Pelaburan'],news:['News & Events','Berita & Acara'],facilities:['Facilities & Resources','Kemudahan & Sumber'],contact:['Contact','Hubungi Kami']};
let page=location.pathname.split('/').pop().replace('.html','')||'index';if(!pages[page])page='index';
const url=(p)=>`${p}.html?lang=${lang}`;
const link=(p,en,ms,cls='text-link')=>`<a class="${cls}" href="${url(p)}">${t(en,ms)} <span aria-hidden="true">↗</span></a>`;
const tag=(en,ms)=>`<div class="eyebrow">${t(en,ms)}</div>`;
const heading=(en,ms,suben='',subms='')=>`<div class="section-heading"><div>${tag(suben,subms)}<h2>${t(en,ms)}</h2></div></div>`;
const btn=(en,ms,id)=>`<button class="text-link" data-detail="${id}">${t(en,ms)} <span aria-hidden="true">↗</span></button>`;
const intro=(en,ms,descen,descms)=>`<section class="page-intro wrap"><div class="breadcrumb">${link('index','Home','Utama')} / ${t(...pages[page])}</div>${tag('SARAWAK · BRUNEI DARUSSALAM','SARAWAK · BRUNEI DARUSSALAM')}<h1>${t(en,ms)}</h1><p class="lead">${t(descen,descms)}</p></section>`;
const experiences=[
 {cat:'nature',image:0,title:['Gunung Mulu & Niah National Parks','Taman Negara Gunung Mulu & Niah'],text:['Discover dramatic limestone landscapes, ancient caves and the remarkable biodiversity of Sarawak.','Terokai landskap batu kapur, gua purba dan kepelbagaian biologi Sarawak yang menakjubkan.'],detail:['Begin your journey by choosing a park and travel dates. Access, guided activities and accommodation should be confirmed with the relevant park operator before travelling. Our proposed tourism enquiry service connects visitors with information for planning their visit.','Mulakan perjalanan dengan memilih taman dan tarikh lawatan. Sahkan akses, aktiviti berpandu dan penginapan dengan pengendali taman sebelum perjalanan. Perkhidmatan pertanyaan pelancongan yang dicadangkan membantu pengunjung merancang lawatan.']},
 {cat:'culture',image:1,title:['Arts, Crafts & Living Longhouses','Seni, Kraf & Kehidupan Rumah Panjang'],text:['Meet the stories behind woven textiles, traditional craftsmanship and the communities that keep them alive.','Hayati kisah di sebalik tenunan, pertukangan tradisional dan komuniti yang memelihara warisan ini.'],detail:['Explore craft traditions and community-led cultural experiences. Visits to longhouses should be arranged with a host or local guide, respecting community customs and asking permission before taking photographs.','Terokai tradisi kraf dan pengalaman budaya kendalian komuniti. Aturkan lawatan rumah panjang bersama tuan rumah atau pemandu tempatan, hormati adat komuniti dan minta izin sebelum mengambil gambar.']},
 {cat:'food',image:2,title:['Culinary Odyssey & Food Trails','Kembara Kulinari & Jejak Makanan'],text:['Discover Sarawak through its flavours, from a comforting bowl of laksa to bustling local markets.','Kenali Sarawak melalui cita rasanya, daripada semangkuk laksa hingga pasar tempatan yang meriah.'],detail:['Build a food trail around local markets and neighbourhood eateries. Ask individual venues about ingredients, dietary needs and halal certification where relevant.','Rancang jejak makanan melalui pasar tempatan dan kedai makan kejiranan. Semak ramuan, keperluan pemakanan dan pensijilan halal dengan premis yang berkaitan.']},
 {cat:'river',image:3,title:['River Journeys & Highland Escapes','Kembara Sungai & Percutian Tanah Tinggi'],text:['Slow down along the waterfront and discover a different perspective on Borneo.','Nikmati ketenangan tepian sungai dan temui sisi Borneo yang berbeza.'],detail:['Discover waterfront walks, river excursions and scenic escapes. Check routes, weather and operator availability when arranging your itinerary.','Terokai laluan tepian sungai, persiaran sungai dan percutian berpemandangan indah. Semak laluan, cuaca dan ketersediaan pengendali semasa merancang jadual perjalanan.']}
];
const services=[
 {title:['Sarawak Exporter Directory','Direktori Pengeksport Sarawak'],text:['Explore a proposed directory of businesses, products and export capabilities.','Terokai cadangan direktori perniagaan, produk dan keupayaan eksport.'],detail:['The proposed directory would let visitors search by product category and business profile. Verified company records and an editorial approval process would be added during full development. No real companies are listed in this prototype.','Direktori yang dicadangkan membolehkan carian mengikut kategori produk dan profil perniagaan. Rekod syarikat yang disahkan serta proses kelulusan kandungan akan ditambah semasa pembangunan penuh. Tiada syarikat sebenar disenaraikan dalam prototaip ini.']},
 {title:['Bilateral Business Matching','Padanan Perniagaan Dua Hala'],text:['Start a conversation with potential partners across Sarawak and Brunei.','Mulakan perbincangan bersama bakal rakan niaga di Sarawak dan Brunei.'],detail:['A proposed matching request captures your industry, business interests and preferred meeting format. The team can then review your requirements and help identify appropriate introductions. Use the demo enquiry form to explore this journey.','Permohonan padanan yang dicadangkan merangkumi industri, minat perniagaan dan format mesyuarat pilihan anda. Pasukan boleh menyemak keperluan dan membantu mengenal pasti rakan niaga yang sesuai. Gunakan borang demo untuk mencuba proses ini.']},
 {title:['Exporter Verification','Semakan Pengeksport'],text:['Find out what information is needed to support a business profile.','Ketahui maklumat yang diperlukan untuk menyokong profil perniagaan.'],detail:['This proposed enquiry route would explain the documents and review steps needed for a directory listing. Verification criteria require client confirmation; the prototype does not verify or endorse any business.','Saluran pertanyaan yang dicadangkan menerangkan dokumen dan langkah semakan untuk penyenaraian direktori. Kriteria pengesahan perlu disahkan oleh klien; prototaip ini tidak mengesahkan atau menyokong mana-mana perniagaan.']},
 {title:['Customs & Cross-Border Logistics','Kastam & Logistik Rentas Sempadan'],text:['Find a starting point for questions about moving products across borders.','Dapatkan panduan awal untuk pertanyaan penghantaran produk merentas sempadan.'],detail:['Tell the team your product category, origin and intended destination. The proposed service can direct enquiries to relevant official information. Actual permits, duties and customs requirements must be checked with the responsible authorities.','Nyatakan kategori produk, lokasi asal dan destinasi kepada pasukan. Perkhidmatan yang dicadangkan boleh mengarahkan pertanyaan kepada maklumat rasmi berkaitan. Permit, duti dan keperluan kastam sebenar mesti disemak dengan pihak berkuasa berkenaan.']}
];
const sectors=[
 [['Renewable Energy & Hydrogen','Tenaga Boleh Baharu & Hidrogen'],['Explore opportunities around cleaner energy and supporting supply chains.','Terokai peluang tenaga lebih bersih serta rantaian bekalan sokongannya.']],
 [['High-Tech Agro & Food Security','Agroteknologi & Keterjaminan Makanan'],['Connect ideas in food production, processing and agricultural innovation.','Hubungkan idea dalam pengeluaran makanan, pemprosesan dan inovasi pertanian.']],
 [['Eco-Tourism Infrastructure','Infrastruktur Ekopelancongan'],['Explore visitor experiences that respect nature and local communities.','Terokai pengalaman pengunjung yang menghormati alam dan komuniti setempat.']],
 [['Digital Economy & Data Centres','Ekonomi Digital & Pusat Data'],['Discover themes in connectivity, digital services and infrastructure.','Kenali bidang kesalinghubungan, perkhidmatan digital dan infrastruktur.']]
];
const news=[
 {image:4,title:['Bilateral business networking session','Sesi jaringan perniagaan dua hala'],cat:['Trade','Perdagangan'],text:['A sample story showing how business engagement and partnership updates could be presented.','Contoh berita yang menunjukkan penyampaian perkembangan kerjasama dan hubungan perniagaan.']},
 {image:5,title:['Discover Sarawak: tourism showcase','Terokai Sarawak: pameran pelancongan'],cat:['Tourism','Pelancongan'],text:['A sample event feature introducing Sarawak’s destinations, culture and hospitality.','Contoh sorotan acara yang memperkenalkan destinasi, budaya dan layanan mesra Sarawak.']},
 {image:6,title:['Exploring opportunities in green energy','Meneroka peluang tenaga hijau'],cat:['Investment','Pelaburan'],text:['A sample editorial layout for investment dialogues and sector-focused updates.','Contoh susun atur editorial untuk dialog pelaburan dan perkembangan sektor.']}
];
function tourismCards(){return experiences.map((x,i)=>`<article class="photo-card" data-category="${x.cat}"><button class="image-button" data-detail="exp${i}" aria-label="${t(...x.title)}"><img src="assets/photo-${x.image}.jpg" alt="${t(...x.title)}" loading="lazy"><span class="image-chip">${t('DISCOVER SARAWAK','TEROKAI SARAWAK')}</span></button><div class="card-body"><h3>${t(...x.title)}</h3><p>${t(...x.text)}</p>${btn('Explore experience','Terokai pengalaman','exp'+i)}</div></article>`).join('')}
function tradeCards(){return services.map((x,i)=>`<article class="card"><div class="icon">${['▤','↔','✓','◇'][i]}</div><h3>${t(...x.title)}</h3><p>${t(...x.text)}</p>${btn('Learn more','Ketahui lanjut','srv'+i)}</article>`).join('')}
function sectorCards(){return sectors.map(x=>`<article class="card"><div class="icon">✧</div><h3>${t(...x[0])}</h3><p>${t(...x[1])}</p></article>`).join('')}
function newsCards(){return news.map((x,i)=>`<article class="photo-card" data-news="${i}"><button class="image-button" data-detail="news${i}" aria-label="${t(...x.title)}"><img src="assets/photo-${x.image}.jpg" alt="${t('Illustrative image for','Imej ilustrasi untuk')} ${t(...x.title)}" loading="lazy"><span class="image-chip">${t('SAMPLE STORY','CONTOH BERITA')}</span></button><div class="card-body">${tag(...x.cat)}<h3>${t(...x.title)}</h3><p>${t(...x.text)}</p>${btn('Read story','Baca berita','news'+i)}</div></article>`).join('')}
function form(kind='contact'){return `<form class="enquiry-form card"><h3>${t(kind==='investment'?'STATOB Investment Desk':'Send an enquiry',kind==='investment'?'Meja Pelaburan STATOB':'Hantar pertanyaan')}</h3><p class="small">${t('Prototype form — no information is sent or saved.','Borang prototaip — tiada maklumat dihantar atau disimpan.')}</p><div class="form-grid"><label>${t('Full name','Nama penuh')}<input name="name" autocomplete="name" required maxlength="100"></label><label>${t('Email address','Alamat e-mel')}<input name="email" type="email" autocomplete="email" required></label><label>${t('Company / organisation','Syarikat / organisasi')}<input name="company" maxlength="150"></label><label>${t('Area of interest','Bidang minat')}<select name="interest">${['trade','tourism','investment','facilities'].map(x=>`<option ${kind===x?'selected':''}>${t(...pages[x])}</option>`).join('')}</select></label></div><label>${t('Your message','Mesej anda')}<textarea name="message" rows="4" required maxlength="2000"></textarea></label><button class="button primary" type="submit">${t('Preview enquiry','Pratonton pertanyaan')} ↗</button><p class="form-status" role="status"></p></form>`}
function pillars(){return `<div class="grid three">${[['trade','Trade & Commerce','Perdagangan','Connect businesses. Expand possibilities.','Hubungkan perniagaan. Luaskan peluang.'],['tourism','Tourism & Culture','Pelancongan & Budaya','Discover the places and people of Sarawak.','Kenali destinasi dan masyarakat Sarawak.'],['investment','Investment Promotion','Promosi Pelaburan','Explore a shared future of opportunity.','Terokai masa depan bersama yang penuh peluang.']].map((x,i)=>`<article class="card"><div class="icon">${['▤','◎','↗'][i]}</div>${tag('0'+(i+1),'0'+(i+1))}<h3>${t(x[1],x[2])}</h3><p>${t(x[3],x[4])}</p>${link(x[0],'Explore this sector','Terokai sektor ini')}</article>`).join('')}</div>`}
function welcome(){return `<section class="section white"><div class="wrap split"><div>${tag('WELCOME TO STATOB','SELAMAT DATANG KE STATOB')}<h2>${t('A Strategic Gateway Fostering Cross-Border Prosperity','Gerbang Strategik Memacu Kemakmuran Rentas Sempadan')}</h2><p>${t('Bringing Sarawak and Brunei closer through trade, tourism and investment. This proposed digital gateway makes it easier for businesses and visitors to explore opportunities and start meaningful conversations.','Merapatkan hubungan Sarawak dan Brunei melalui perdagangan, pelancongan dan pelaburan. Gerbang digital yang dicadangkan ini memudahkan perniagaan dan pengunjung meneroka peluang serta memulakan perbincangan bermakna.')}</p>${link('about','Learn about STATOB','Kenali STATOB')}</div><aside class="focus-panel">${tag('SHARED HORIZONS','WAWASAN BERSAMA')}${[['Bilateral connections','Hubungan dua hala','Connecting people and opportunities across borders.','Menghubungkan masyarakat dan peluang merentas sempadan.'],['Business partnerships','Kerjasama perniagaan','A place to begin your next business conversation.','Tempat untuk memulakan perbincangan perniagaan seterusnya.'],['Borneo discovery','Penemuan Borneo','Celebrating our landscapes, cultures and communities.','Meraikan landskap, budaya dan komuniti kita.']].map(x=>`<div class="focus-row"><span class="icon">◇</span><div><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p></div></div>`).join('')}</aside></div></section>`}
function resources(){return `<div class="grid three">${[['Business Centre & Meeting Suites','Pusat Perniagaan & Bilik Mesyuarat','Explore a proposed facility enquiry and meeting request journey.','Terokai cadangan proses pertanyaan kemudahan dan permohonan mesyuarat.','facility'],['Brochures & Publications','Brosur & Penerbitan','Preview the proposed resource library and download a sample guide.','Pratonton pustaka sumber dan muat turun panduan contoh.','download'],['Media & Gallery','Media & Galeri','Explore the imagery behind this website concept.','Terokai imej di sebalik konsep laman web ini.','gallery']].map(x=>`<article class="card"><div class="icon">▧</div><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p>${btn('Explore resource','Terokai sumber',x[4])}</article>`).join('')}</div>`}
const home=()=>`<section class="hero wrap">${tag('SARAWAK TRADE & TOURISM OFFICE BRUNEI DARUSSALAM','PEJABAT PERDAGANGAN & PELANCONGAN SARAWAK BRUNEI DARUSSALAM')}<h1>${t('Discover Sarawak. Connect Opportunities.','Terokai Sarawak. Hubungkan Peluang.')}</h1><p class="lead">${t('Bridging Sarawak and Brunei through trade, tourism, investment, and meaningful partnerships across Borneo.','Menghubungkan Sarawak dan Brunei melalui perdagangan, pelancongan, pelaburan dan kerjasama bermakna di seluruh Borneo.')}</p><div class="actions">${link('tourism','Explore Sarawak','Terokai Sarawak','button primary')}${link('trade','Discover opportunities','Temui peluang','button secondary')}</div><div class="hero-picture"><img src="assets/hero.jpeg" alt="${t('Concept illustration of Sarawak and Brunei landmarks linked by coloured ribbons','Ilustrasi konsep mercu tanda Sarawak dan Brunei dihubungkan reben berwarna')}"></div><div class="hero-caption"><span>SARAWAK · MALAYSIA</span><span>${t('SHARED HORIZONS & PROSPERITY','WAWASAN & KEMAKMURAN BERSAMA')}</span><span>BRUNEI DARUSSALAM</span></div></section>${welcome()}<section class="section wrap">${heading('Our Core Strategic Pillars','Teras Strategik Kami','OUR MANDATE','MANDAT KAMI')}${pillars()}</section><section class="section white"><div class="wrap">${heading('Land of Untold Wonders','Bumi Penuh Keajaiban','DISCOVER SARAWAK','TEROKAI SARAWAK')}<div class="grid two">${tourismCards()}</div><div class="section-end">${link('tourism','Explore all experiences','Terokai semua pengalaman')}</div></div></section><section class="section wrap">${heading('Trade Directory & Business Gateways','Direktori Perdagangan & Gerbang Perniagaan','BUILDING CONNECTIONS','MEMBINA HUBUNGAN')}<div class="grid four">${tradeCards()}</div></section><section class="section warm"><div class="wrap split"><div>${heading('High-Impact Investment Sectors','Sektor Pelaburan Berimpak Tinggi','INVEST IN TOMORROW','MELABUR UNTUK MASA DEPAN')}<div class="grid two">${sectorCards()}</div></div>${form('investment')}</div></section><section class="section white"><div class="wrap">${heading('News & Events','Berita & Acara','FROM THE REGION','DARI RANTAU INI')}<p class="sample-note">${t('Illustrative stories and images for proposal demonstration.','Berita dan imej ilustrasi untuk demonstrasi cadangan.')}</p><div class="grid three">${newsCards()}</div><div class="section-end">${link('news','Visit the newsroom','Lawati ruangan berita')}</div></div></section><section class="section wrap">${heading('Facilities, Gallery & Downloads','Kemudahan, Galeri & Muat Turun','AT YOUR SERVICE','UNTUK ANDA')}${resources()}</section>${contactSection()}`;
function contactSection(){return `<section class="section white"><div class="wrap split"><div>${tag('LET’S CONNECT','MARI BERHUBUNG')}<h2>${t('Get in Touch with STATOB','Hubungi STATOB')}</h2><p>${t('Tell us what you are looking for. Explore how visitors could request information, discuss a partnership or arrange a meeting.','Maklumkan keperluan anda. Terokai cara pengunjung memohon maklumat, membincangkan kerjasama atau mengatur mesyuarat.')}</p><div class="contact-box"><h3>${t('Sarawak · Brunei Darussalam','Sarawak · Brunei Darussalam')}</h3><p>${t('Office address, opening hours and official contact details will be confirmed before launch.','Alamat pejabat, waktu operasi dan maklumat hubungan rasmi akan disahkan sebelum pelancaran.')}</p></div></div>${form()}</div></section>`}
const contents={
 index:home,
 about:()=>intro('Connecting People. Creating Possibilities.','Menghubungkan Masyarakat. Mencipta Peluang.','A proposed digital gateway for Sarawak–Brunei trade, tourism and investment.','Cadangan gerbang digital untuk perdagangan, pelancongan dan pelaburan Sarawak–Brunei.')+welcome()+`<section class="section wrap">${heading('Three pillars. One shared horizon.','Tiga teras. Satu wawasan bersama.')}${pillars()}</section><section class="section warm"><div class="wrap narrow"><h2>${t('Designed around your next step','Direka untuk langkah anda seterusnya')}</h2><p>${t('Whether you are exploring Sarawak, looking for business connections or considering an investment discussion, the proposed website brings relevant information and enquiry routes together.','Sama ada anda ingin menerokai Sarawak, mencari hubungan perniagaan atau membincangkan pelaburan, laman web yang dicadangkan menyatukan maklumat dan saluran pertanyaan berkaitan.')}</p>${link('contact','Start a conversation','Mulakan perbincangan','button primary')}</div></section>`,
 tourism:()=>intro('Land of Untold Wonders','Bumi Penuh Keajaiban','Nature, culture, flavour and discovery. Find your own way into Sarawak.','Alam, budaya, cita rasa dan penemuan. Temui cara anda sendiri untuk mengenali Sarawak.')+`<section class="section white"><div class="wrap"><div class="filters" role="group" aria-label="${t('Experience filters','Penapis pengalaman')}">${[['all','All experiences','Semua pengalaman'],['nature','Nature & wildlife','Alam & hidupan liar'],['culture','Arts & culture','Seni & budaya'],['food','Food trails','Jejak makanan'],['river','River journeys','Kembara sungai']].map((x,i)=>`<button class="filter ${i===0?'active':''}" data-filter="${x[0]}" aria-pressed="${i===0}">${t(x[1],x[2])}</button>`).join('')}</div><div class="grid two">${tourismCards()}</div></div></section><section class="section wrap narrow"><h2>${t('Your journey starts with a conversation','Perjalanan anda bermula dengan perbincangan')}</h2><p>${t('Ask about destinations and the information you need to plan your visit.','Tanya tentang destinasi dan maklumat yang diperlukan untuk merancang lawatan anda.')}</p>${link('contact','Plan your visit','Rancang lawatan anda','button primary')}</section>`,
 trade:()=>intro('Connections That Move Business Forward','Hubungan yang Memajukan Perniagaan','Explore proposed pathways for exporters, business partners and cross-border enquiries.','Terokai cadangan saluran untuk pengeksport, rakan niaga dan pertanyaan rentas sempadan.')+`<section class="section white"><div class="wrap grid four">${tradeCards()}</div></section><section class="section wrap">${heading('From introduction to opportunity','Daripada perkenalan kepada peluang','YOUR BUSINESS JOURNEY','PERJALANAN PERNIAGAAN ANDA')}<div class="grid three">${[['01','Tell us your goals','Nyatakan matlamat anda','Share your sector, products and target market.','Kongsikan sektor, produk dan pasaran sasaran anda.'],['02','Explore relevant connections','Terokai hubungan berkaitan','Identify the information and introductions you need.','Kenal pasti maklumat dan pengenalan yang diperlukan.'],['03','Start the conversation','Mulakan perbincangan','Request a follow-up or an introductory meeting.','Mohon tindakan susulan atau mesyuarat pengenalan.']].map(x=>`<article class="card">${tag(x[0],x[0])}<h3>${t(x[1],x[2])}</h3><p>${t(x[3],x[4])}</p></article>`).join('')}</div></section>`+contactSection(),
 investment:()=>intro('Invest in a Shared Tomorrow','Melabur untuk Masa Depan Bersama','Explore sector themes and begin a discussion about your investment interests.','Terokai tema sektor dan mulakan perbincangan mengenai minat pelaburan anda.')+`<section class="section white"><div class="wrap split"><div><div class="grid two">${sectorCards()}</div><p class="sample-note">${t('Sector themes are illustrative; specific projects and incentives require confirmation.','Tema sektor adalah ilustrasi; projek dan insentif khusus memerlukan pengesahan.')}</p></div>${form('investment')}</div></section>`,
 news:()=>intro('News, Ideas & Connections','Berita, Idea & Hubungan','A preview of the proposed newsroom for updates from Sarawak and Brunei.','Pratonton ruangan berita yang dicadangkan untuk perkembangan Sarawak dan Brunei.')+`<section class="section white"><div class="wrap"><label class="search-label">${t('Search sample stories','Cari contoh berita')}<input id="news-search" type="search" placeholder="${t('Search by title or topic…','Cari mengikut tajuk atau topik…')}"></label><p class="sample-note">${t('All stories below are demonstration content, not reports of actual events.','Semua berita di bawah ialah kandungan demonstrasi, bukan laporan acara sebenar.')}</p><div class="grid three">${newsCards()}</div><p id="empty" hidden role="status">${t('No matching stories. Try another keyword.','Tiada berita sepadan. Cuba kata kunci lain.')}</p></div></section>`,
 facilities:()=>intro('Space to Meet. Resources to Explore.','Ruang Bertemu. Sumber untuk Diterokai.','Preview facilities enquiries, publications and a visual gallery.','Pratonton pertanyaan kemudahan, penerbitan dan galeri visual.')+`<section class="section white"><div class="wrap">${resources()}</div></section><section class="section wrap" id="gallery">${heading('A glimpse of Sarawak','Sekilas Sarawak','CONCEPT IMAGE GALLERY','GALERI IMEJ KONSEP')}<div class="grid two">${experiences.map((x,i)=>`<button class="gallery-tile" data-detail="exp${i}"><img src="assets/photo-${i}.jpg" alt="${t(...x.title)}" loading="lazy"><span>${t(...x.title)} ↗</span></button>`).join('')}</div></section>`,
 contact:()=>intro('Let’s Start a Conversation','Mari Mulakan Perbincangan','Business, tourism or investment — find the right starting point.','Perniagaan, pelancongan atau pelaburan — temui langkah permulaan yang tepat.')+contactSection()
};
const navLink=(p)=>`<a href="${url(p)}" ${p===page?'aria-current="page"':''}>${t(...pages[p])}${p===page?'<span class="current-dot" aria-hidden="true"></span>':''}</a>`;
function navGroup(id,en,ms,children){
 const active=children.includes(page);
 return `<div class="nav-group ${active?'is-current':''}"><button class="nav-trigger" id="${id}-trigger" aria-expanded="false" aria-controls="${id}-dropdown">${t(en,ms)}<svg class="chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>${active?'<span class="sr-only">'+t(' — current section',' — bahagian semasa')+'</span>':''}</button><div class="nav-dropdown" id="${id}-dropdown" aria-labelledby="${id}-trigger" hidden>${children.map(navLink).join('')}</div></div>`;
}
function applyTheme(theme){
 document.documentElement.dataset.theme=theme;
 try{localStorage.setItem('statob-theme',theme)}catch{}
 const b=$('#theme-toggle');
 const dark=theme==='dark';
 b.setAttribute('aria-pressed',String(dark));
 b.setAttribute('aria-label',t('Dark mode','Mod gelap'));
 b.title=dark?t('Switch to light mode','Tukar kepada mod cerah'):t('Switch to dark mode','Tukar kepada mod gelap');
 b.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20.6 14.2A9 9 0 0 1 9.8 3.4 9 9 0 1 0 20.6 14.2Z"/>'}</svg><span>${dark?t('Light','Cerah'):t('Dark','Gelap')}</span>`;
}
function closeDropdowns(){document.querySelectorAll('.nav-trigger').forEach(b=>{b.setAttribute('aria-expanded','false');document.getElementById(b.getAttribute('aria-controls')).hidden=true})}
document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))closeDropdowns()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const expanded=document.querySelector('.nav-trigger[aria-expanded="true"]');if(expanded){closeDropdowns();expanded.focus()}else if($('#menu').getAttribute('aria-expanded')==='true'){$('#menu').setAttribute('aria-expanded','false');$('#navigation').classList.remove('open');$('#menu').focus()}}});
document.addEventListener('focusin',e=>{if(!e.target.closest('.nav-group'))closeDropdowns();else document.querySelectorAll('.nav-group').forEach(g=>{if(!g.contains(e.target)){g.querySelector('.nav-trigger').setAttribute('aria-expanded','false');g.querySelector('.nav-dropdown').hidden=true}})});
function render(){
 document.documentElement.lang=lang;document.title=`${t(...pages[page])} | STATOB — ${t('Prototype','Prototaip')}`;
 $('#app').innerHTML=`<a class="skip" href="#main">${t('Skip to content','Langkau ke kandungan')}</a><header><div class="wrap header-inner"><a class="brand" href="${url('index')}"><img src="assets/logo.png" alt="STATOB"><span>STATOB<small>${t('Sarawak Trade & Tourism Office Brunei','Pejabat Perdagangan & Pelancongan Sarawak Brunei')}</small></span></a><button id="menu" class="menu-button" aria-expanded="false" aria-controls="navigation">${t('Menu','Menu')} ☰</button><nav id="navigation" aria-label="${t('Main navigation','Navigasi utama')}">${navLink('index')}${navLink('about')}${navGroup('explore','Explore','Terokai',['tourism','trade','investment'])}${navGroup('resources','Resources','Sumber',['news','facilities'])}${navLink('contact')}</nav><button id="theme-toggle" class="theme-toggle" type="button"></button><div class="language" aria-label="${t('Language','Bahasa')}"><button data-lang="en" aria-pressed="${lang==='en'}">EN</button><span>/</span><button data-lang="ms" aria-pressed="${lang==='ms'}">BM</button></div></div></header><main id="main">${contents[page]()}</main><footer><div class="wrap footer-grid"><div><a class="brand" href="${url('index')}"><img src="assets/logo.png" alt="STATOB"><span>STATOB</span></a><p>${t('Connecting Sarawak and Brunei through trade, tourism and shared possibilities.','Menghubungkan Sarawak dan Brunei melalui perdagangan, pelancongan dan peluang bersama.')}</p></div><div><h3>${t('Explore','Terokai')}</h3>${['about','trade','tourism','investment'].map(p=>link(p,...pages[p])).join('')}</div><div><h3>${t('Useful links','Pautan berguna')}</h3>${['news','facilities','contact'].map(p=>link(p,...pages[p])).join('')}</div></div><div class="wrap footer-bottom"><span>STATOB · ${t('Website design proposal','Cadangan reka bentuk laman web')}</span><span>${t('Prototype · Sample content · Forms do not send data','Prototaip · Kandungan contoh · Borang tidak menghantar data')}</span></div></footer><dialog id="detail"><button id="close-dialog" class="close" aria-label="${t('Close','Tutup')}">×</button><div id="dialog-content"></div></dialog>`;
 applyTheme(document.documentElement.dataset.theme||'light');
 $('#theme-toggle').onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
 document.querySelectorAll('.nav-trigger').forEach(b=>{
  b.onclick=()=>{const open=b.getAttribute('aria-expanded')!=='true';closeDropdowns();b.setAttribute('aria-expanded',String(open));document.getElementById(b.getAttribute('aria-controls')).hidden=!open};
  b.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();closeDropdowns();b.setAttribute('aria-expanded','true');const menu=document.getElementById(b.getAttribute('aria-controls'));menu.hidden=false;menu.querySelector('a').focus()}};
 });
 document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('statob-language',lang);history.replaceState({},'',url(page));const y=scrollY;render();scrollTo(0,y)});
 $('#menu').onclick=()=>{const open=$('#menu').getAttribute('aria-expanded')!=='true';$('#menu').setAttribute('aria-expanded',open);$('#navigation').classList.toggle('open',open);if(!open)closeDropdowns()};
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));
 $('#close-dialog').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
 document.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();f.querySelector('.form-status').textContent=t('Demo complete. Your enquiry is ready for review. Nothing has been sent or saved.','Demo selesai. Pertanyaan anda sedia untuk disemak. Tiada maklumat dihantar atau disimpan.')});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)});
 if($('#news-search'))$('#news-search').oninput=e=>{let count=0;document.querySelectorAll('[data-news]').forEach(c=>{c.hidden=!c.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!c.hidden)count++});$('#empty').hidden=count>0};
}
function detail(id){
 if(id==='gallery'){if(page==='facilities'){$('#gallery').scrollIntoView({behavior:'smooth'});return}location.href=url('facilities')+'#gallery';return}
 let title,body,img;
 if(id.startsWith('exp')){let x=experiences[+id.slice(3)];title=t(...x.title);body=t(...x.detail);img=x.image}
 else if(id.startsWith('srv')){let x=services[+id.slice(3)];title=t(...x.title);body=t(...x.detail)}
 else if(id.startsWith('news')){let x=news[+id.slice(4)];title=t(...x.title);img=x.image;body=t(...x.text)+' '+t('This is a sample article for the client proposal. The final newsroom can support approved articles, event dates, categories and an archive. This story does not describe a verified event.','Ini ialah contoh artikel untuk cadangan klien. Ruangan berita akhir boleh menyokong artikel yang diluluskan, tarikh acara, kategori dan arkib. Berita ini tidak menerangkan acara yang disahkan.')}
 else if(id==='facility'){title=t('Plan a meeting','Rancang mesyuarat');body=t('The proposed facility enquiry journey would collect your preferred date, number of attendees and meeting needs. Room details, availability and booking terms will be confirmed by the client before development.','Proses pertanyaan kemudahan yang dicadangkan mengumpulkan tarikh pilihan, bilangan peserta dan keperluan mesyuarat. Butiran bilik, ketersediaan dan syarat tempahan akan disahkan oleh klien sebelum pembangunan.')}
 else if(id==='download'){title=t('Sample visitor guide','Contoh panduan pengunjung');body=t('Download a bilingual sample guide created for this prototype. It demonstrates the download experience and is not an official publication.','Muat turun contoh panduan dwibahasa yang disediakan untuk prototaip ini. Ia menunjukkan pengalaman muat turun dan bukan penerbitan rasmi.')}
 $('#dialog-content').innerHTML=`${img!==undefined?`<img class="dialog-image" src="assets/photo-${img}.jpg" alt="${title}">`:''}${tag('PROTOTYPE PREVIEW','PRATONTON PROTOTAIP')}<h2>${title}</h2><p>${body}</p>${id==='download'?`<a class="button primary" href="assets/sample-guide.txt" download>${t('Download sample guide','Muat turun panduan contoh')} ↓</a>`:link('contact','Make an enquiry','Buat pertanyaan','button primary')}`;$('#detail').showModal();
}
render();
